times=[i*0.5 for i in range(31)]
def mk(d):
    out=[]
    for t in times:
        if t in d:
            x,y,w,h=[round(v,2) for v in d[t]]; out.append({"t":t,"x":x,"y":y,"w":w,"h":h})
        else: out.append({"t":t,"off":True})
    return out
